//! Independent ordinary rune altar World actions; pinned Wiki recipe facts, no developer tests invoked.
use gielinor_world::{simulation::{World,PlayerData,ActorId,Action,WorldEvent},runecrafting::{Config,Recipe},locations::Location,loc_collision::{self,LocCollision},inventory::Item,stats::Stats,npc::RandomSource,CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("ordinary rune binding unexpectedly drew RNG")}}
const ROWS:[(u32,i32,u8,u16,u8);6]=[(34760,556,1,50,11),(34761,558,2,55,14),(34762,555,5,60,19),(34763,557,9,65,26),(34764,554,14,70,35),(34765,559,20,75,46)];
fn fixture(row:usize,member:bool,kind:usize,current:u8,count:usize,rate:i32)->(World,ActorId,Location,Vec<(usize,i32)>){let(id,output,level,xp,interval)=ROWS[row];let mut w=World::default();for x in [3216,3224]{for z in [3216,3224]{w.collision.allocate(x,z,0);}}let location=Location::new(CoordGrid::new(3221,3220,0).unwrap(),id,10,0).unwrap();let ty=LocCollision{width:3,length:3,block_walk:2,block_range:true,break_route_finding:false};w.location_types.insert(id,ty);w.locations.load(location);loc_collision::toggle(&mut w.collision,location.coords,location.shape,location.angle,ty,true).unwrap();w.runecrafting=Some(Config{altars:[(id,Recipe{output,level,xp_tenths:xp,interval,name:"independent rune"})].into(),blocked_held:[24704,26879,28593,28595,28597,28599].into(),blocked_worn:[26850].into(),animation:791,spot:186});w.object_types.stackable.insert(output);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(20,99);stats.set_current(20,current as i8);stats.set_fine_xp(20,130344311).unwrap();let mut d=PlayerData::new(1,"Independent rune binder".into(),CoordGrid::new(3220,3220,0).unwrap(),stats);d.xp_rate_hundreds=rate;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==27{995}else{1931},count:if s==27{1000}else{1},vars:0})).unwrap();}let mut parts=vec![];for k in 0..count{let slot=(k*9+7)%28;let id=match kind{0=>1436,1=>7936,_=>if k%2==0{1436}else{7936}};d.inventory.restore_slot(slot,Some(Item{id,count:1,vars:0})).unwrap();parts.push((slot,id));}d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();d.equipment.restore_slot(4,Some(Item{id:1129,count:1,vars:9})).unwrap();w.queue_login(1,d).unwrap();w.tick_with_random(&mut NoDraw).unwrap();let actor=w.actors().next().unwrap();w.set_membership(actor,member).unwrap();w.drain_events();(w,actor,location,parts)}
fn request(w:&mut World,a:ActorId,location:Location){assert!(w.has_location_handler(location.id,1));assert!(!w.has_location_handler(location.id,2));w.submit(a,Action::OperateLocation{coords:location.coords,id:location.id,operation:1,control:false}).unwrap();w.tick_with_random(&mut NoDraw).unwrap();}
#[test]fn nine_hundred_seventy_two_registered_altar_material_membership_rate_and_level_controls(){let mut n=0;for row in 0..6{let(_,output,level,xp,interval)=ROWS[row];for member in[false,true]{for kind in 0..3{for current in[level,99,104]{for count in[1usize,7,28]{for rate in[100,125,500]{let(mut w,a,location,parts)=fixture(row,member,kind,current,count,rate);let before=w.data(a).unwrap().clone();let mut bag=before.inventory.clone();for(slot,_)in &parts{bag.restore_slot(*slot,None).unwrap();}let gap=parts.iter().map(|p|p.0).min().unwrap();let produced=count as i32*(i32::from(current/interval)+1);bag.restore_slot(gap,Some(Item{id:output,count:produced,vars:0})).unwrap();let mut stats=before.stats.clone();stats.set_fine_xp(20,stats.fine_xp(20)+count as i32*i32::from(xp)*rate/100).unwrap();let start=w.clock.0;request(&mut w,a,location);assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);let events=w.drain_events();assert!(events.iter().any(|e|matches!(e,WorldEvent::PlayerCombatAnimation{sequence:791,..})));assert!(events.iter().any(|e|matches!(e,WorldEvent::PlayerSpotAnimation{spot:186,height:100,..})));w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.clock.0-1,start+1);let d=w.data(a).unwrap();assert_eq!(d.inventory,bag,"row{row} member{member} kind{kind} current{current} count{count} rate{rate}");assert_eq!(d.stats,stats);assert_eq!(d.equipment,before.equipment);for _ in 0..3{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().stats,stats);request(&mut w,a,location);for _ in 0..2{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().stats,stats);assert_eq!(w.data(a).unwrap().equipment,before.equipment);n+=1;}}}}}}assert_eq!(n,972);println!("PG_RUNE_ALTARS independent whole-state action cases={n};all6/RunePureMixed/F2Pmember/count1-7-28/currentmin-99-104/rate1-1.25-5;oneclock/noRNG/emptyrepeat;104isconstructedpredicate,noboostactivationclaim");}
